// Legacy-URL redirect resolver for the pre-rebuild WordPress site.
//
// The old site served every work at /content/<slug>/ (mirrored under the
// /bn/ /gj/ /hi/ /mr/ language subsites), with taxonomy archives at
// /content_category/, /content_tag/, /content_letter/, /author/ and
// /all-categories/. Those paths 404 on the rebuilt site; these functions
// 301 them to their new homes so decades of inbound links keep working.
//
// map.json is generated by scripts/legacy-redirects/generate.py from
// data/prod-mirror/inventory.jsonl + the Wayback CDX snapshot. Re-run it
// after ingesting new works so previously-unmatched slugs upgrade from
// section fallbacks to exact redirects.
import MAP from './map.json';

const STRIP = new Set(['feed', 'embed', 'amp', 'page']);
const GONE_SET = new Set(MAP.gone);
const TRANSLATED = new Set(MAP.translated);

// "/content/<slug>/feed/", ".../page/2/" etc. → "<slug>"
export function slugFrom(pathParam) {
  const segs = (Array.isArray(pathParam) ? pathParam : [pathParam])
    .filter(Boolean)
    .map((s) => {
      try { return decodeURIComponent(s).toLowerCase(); } catch { return s.toLowerCase(); }
    });
  while (segs.length > 1) {
    const last = segs[segs.length - 1];
    if (STRIP.has(last) || /^\d+$/.test(last)) segs.pop();
    else break;
  }
  return segs[0] || '';
}

// lang: new-site language prefix to prefer for translated pages ('gu', 'hi',
// 'mr') or null. Old /gj/ maps to new /gu/.
export function lookup(slug, lang) {
  if (!slug) return null;
  let target = MAP.exact[slug] || MAP.exact[slug.replace(/-\d$/, '')];
  if (target) {
    if (lang && target.startsWith('/')) {
      const hop = `/${lang}${target}`;
      if (TRANSLATED.has(hop)) target = hop;
    }
    return { target };
  }
  if (GONE_SET.has(slug)) return { gone: true };
  const fb = MAP.fallback[slug];
  return fb ? { target: fb } : null;
}

export function gone() {
  return new Response(
    '<!doctype html><meta charset="utf-8"><title>410 Gone</title>' +
      '<p>This page has been permanently removed. Visit the ' +
      '<a href="/">Indian Liberals archive</a>.</p>',
    { status: 410, headers: { 'content-type': 'text/html; charset=utf-8' } },
  );
}

export function redirect(request, target, status = 301) {
  return Response.redirect(new URL(target, request.url).toString(), status);
}

// Handler for /content/-style namespaces: exact map → 410 list → section
// fallback → pass through to the static 404.
export function contentHandler(lang = null) {
  return async ({ request, params, env }) => {
    const hit = lookup(slugFrom(params.path), lang);
    if (hit?.gone) return gone();
    if (hit) return redirect(request, hit.target);
    return env.ASSETS.fetch(request);
  };
}

// Handler for taxonomy archives that have one sensible successor page.
export function sectionHandler(defaultTarget, overrides = {}) {
  return async ({ request, params }) => {
    const term = slugFrom(params.path);
    return redirect(request, overrides[term] || defaultTarget);
  };
}

export function goneHandler() {
  return async () => gone();
}

// Catch-all for the fully-legacy /bn/ and /gj/ subsites.
export function langSiteHandler(lang) {
  return async (ctx) => {
    const { request, params, env } = ctx;
    const segs = (Array.isArray(params.path) ? params.path : [params.path]).filter(Boolean);
    const ns = (segs[0] || '').toLowerCase();
    const rest = segs.slice(1);
    if (!ns) return redirect(request, '/');
    switch (ns) {
      case 'content': {
        const hit = lookup(slugFrom(rest), lang);
        if (hit?.gone) return gone();
        if (hit) return redirect(request, hit.target);
        return redirect(request, '/primary-works/');
      }
      case 'content_category':
      case 'content_tag':
      case 'content_letter':
      case 'all-categories':
        return redirect(request, '/primary-works/');
      case 'about-us':
        return redirect(request, '/about/');
      case 'audios-videos':
        return redirect(request, '/interviews/');
      case 'author':
        return redirect(request, '/');
      case 'wp-json':
      case 'wp-content':
      case 'wp-includes':
        return gone();
      default:
        return env.ASSETS.fetch(request);
    }
  };
}
